/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerValuesRoutes } from './values.controller.ts';

/** Registers the feature routes. */
export function registerValuesModule(router: IRouterApi, services?: IServiceRegistry): void {
  registerValuesRoutes(router, services);
}
